/// <summary>
/// Extension of form InventJournalTable
/// </summary>
[ExtensionOf(formStr(InventJournalTable))]
final class AVAInventJournalTableFrm_Extension
{
}

Method.Source:
/// <summary>
/// Extension of method enableButtonsActive
/// </summary>
void enableButtonsActive()
{
    InventJournalType journalType = journalFormTable.journalTypeId();

    next enableButtonsActive();

    switch (journalType)
    {
        case InventJournalType::project:
            if(inventJournalTable.AVAProjProduction != ''
                && InventJournalTable.Posted == NoYes::No)
            {
                inventJournalTable_ds.allowEdit(false);
                inventJournalTable_ds.allowDelete(false);
            }
            else if(InventJournalTable.AVAProjProduction != '')
            {  
                inventJournalTable_ds.allowEdit(false);
                inventJournalTable_ds.allowDelete(true);
            }
            else
            {
                inventJournalTable_ds.allowEdit(true);
                inventJournalTable_ds.allowDelete(true);
            }
            break;
    }
}
